long double fnd_angle(point p) {
  long double len = sqrt(p.x * p.x + p.y * p.y);
  long double angle = acos(fabs(p.x) / len);
  if (p.y < 0) {
    if (p.x >= 0)
      angle = 2 * PI - angle;
    else
      angle += PI;
  } else if (p.x < 0)
    angle = PI - angle;
  return angle;
}
