    long double dis = sqrt(A[i].x * A[i].x + A[i].y * A[i].y);
    if (dis > 2 * mid) continue;
    long double angle = fnd_angle(A[i]);
    long double angle2 = acos(dis / (2.0 * mid));
    a.push_back({angle - angle2, 2 * angle2});
    b.push_back({angle + angle2, -2.0 * angle2});
  }
