    if (s.size() + 1 >= k) return 1;
    s.insert(a[i].first + a[i].second);
  }
  s.clear();
  for (int i = 0; i < b.size(); i++) {
    while (s.size() > 0 && *(--s.end()) > b[i].first) s.erase(--s.end());
    if (s.size() + 1 >= k) return 1;
    s.insert(b[i].first + b[i].second);
  }
  return mx >= k;
  return (mx >= k);
}
