class BITTree {
 public:
  std::vector<long long> data;
  int size;
  BITTree(int size) {
    this->size = size + 1;
    this->data = std::vector<long long>(size + 1);
  }
  BITTree(std::vector<long long> arr) {
    this->size = arr.size() + 1;
    this->data = std::vector<long long>(size + 1);
    for (int i = 0; i < arr.size(); i++) this->update(i + 1, arr[i]);
  }
  void update(int index, long long value) {
    while (index <= size) {
      data[index] += value;
      index += (index & (-index));
    }
  }
