        dir((b.x < a.x - 1e-9) ? -1 : (a.x < b.x - 1e-9)) {}
  double gety(double x) const {
    if (fabs(b.x - a.x) < 1e-9) {
      assert(fabs(b.y - a.y) < 1e-9);
      return a.y;
    }
