  random_shuffle(begin(p), end(p));
  int n = p.size();
  unordered_map<pair<int, int>, vector<pair<double, double>>> g;
  double r = dist(p[0], p[1]);
  g[hashp(p[0], r)].push_back(p[0]);
  g[hashp(p[1], r)].push_back(p[1]);
  for (int i = 2; i < n; ++i) {
