        int x = new_hash.first + dx;
        int y = new_hash.second + dy;
        if (g.count({x, y})) {
          for (auto point : g[{x, y}]) {
            cands.push_back(point);
          }
        }
      }
    }
    double new_r = r;
    for (auto point : cands) {
      new_r = min(new_r, dist(p[i], point));
