           y1 -= sty, y2 -= sty;
           return 1ll * x1 * y2 - 1ll * x2 * y1 > 0;
         });
    int cur = 0;
    for (int i = l + 1; i < r; ++i) {
      if (tp(i) != tp(l) and cur == 0) {
        line(i, l);
        solve(l + 1, i);
