      ins(1, lp + 1, 1, rp - 1, 2);
      ins(0, 1, 1, rp - 1, 2);
      ins(0, rp, 1, rp - 1, -2);
      ins(0, rp + 1, rp + 1, lp - 1, 1);
      ins(0, lp, rp + 1, lp - 1, -1);
