      ins(0, rp, lp + 1, rp - 1, -2);
      ins(0, 1, 1, lp - 1, 1);
      ins(0, lp, 1, lp - 1, -1);
      ins(0, rp + 1, rp + 1, sz, 1);
      ins(1, rp + 1, 1, lp - 1, 1);
