    for (dat z : G[i][0]) t[0].ins(z.l, z.v), t[0].ins(z.r + 1, -z.v);
    for (dat z : G[i][1]) t[1].ins(z.l, z.v), t[1].ins(z.r + 1, -z.v);
    for (int z : h[i])
      if (i <= z)
