  }
  for (int i = 0; i < n; ++i) {
    for (int j = i + 2; j < n; ++j) {
      if (i + n - j < 2) continue;
      LL a = 0;
      for (int k = i + 1; k < j; ++k) {
        a += det(points[i], points[k], points[k + 1]);
