  void ins(int x, int l, int r, long long a, long long b) {
    if (l != r) {
      if (tree[x].a * l + tree[x].b <= a * l + b &&
          tree[x].a * r + tree[x].b <= a * r + b) {
        tree[x].a = a, tree[x].b = b;
        return;
      }
      if (tree[x].a * l + tree[x].b >= a * l + b &&
          tree[x].a * r + tree[x].b >= a * r + b)
        return;
      if (tree[x].a * ((l + r) >> 1) + tree[x].b < a * ((l + r) >> 1) + b)
        swap(tree[x].a, a), swap(tree[x].b, b);
      if (a < tree[x].a)
        ins(x << 1, l, ((l + r) >> 1), a, b);
      else
        ins(x << 1 | 1, ((l + r) >> 1) + 1, r, a, b);
    } else if (l * a + b > l * tree[x].a + tree[x].b) {
      tree[x] = Node{a, b};
