vector<Point> Convex_hull(vector<Point> P) {
  int n = P.size(), k = 0;
  sort(P.begin(), P.end());
  vector<Point> H(2 * n);
  for (int i = 0; i < n; ++i) {
    while (k >= 2 && Cross(H[k - 2], H[k - 1], P[i]) <= 0) k--;
    H[k++] = P[i];
  }
  int t = k + 1;
  for (int i = n - 2; i >= 0; --i) {
    while (k >= t && Cross(H[k - 2], H[k - 1], P[i]) <= 0) k--;
    H[k++] = P[i];
  }
  H.resize(k - 1);
  return H;
}
