pair<vector<int>, vector<int> > ulHull(const vector<Point<long long> >& S) {
  vector<int> Q((int)(S).size()), U, L;
  iota(Q.begin(), Q.end(), 0);
  sort(Q.begin(), Q.end(), [&S](int a, int b) { return S[a] < S[b]; });
  for (auto& it : Q) {
    while ((int)(U).size() > 1 &&
