void solve(vector<point_t> points) {
  int max_degree = 0, max_id = -1;
  for (int i = 0; i < points.size(); ++i) {
    if (max_degree < points[i].degree) {
      max_degree = points[i].degree;
      max_id = i;
    }
  }
  if (max_degree == 1) {
    for (int i = 0; i < points.size(); ++i) {
      if (!points[i].degree) {
        max_id = i;
      }
    }
    for (int i = 0; i < points.size(); ++i) {
      if (i != max_id) {
        cout << points[i].id + 1 << " " << points[max_id].id + 1 << endl;
      }
    }
  } else {
    int n = points.size() - 1;
    swap(points[max_id], points[n]);
    vector<pair<long double, int>> events;
    for (int i = 0; i < n; ++i) {
      long double from =
          atan2(points[i].y - points[n].y, points[i].x - points[n].x);
      long double to = from + pi;
      if (to > pi) {
        to -= pi * 2;
      }
      events.emplace_back(from, i);
      events.emplace_back(to, i + n);
    }
    sort(events.begin(), events.end());
    vector<bool> side(n);
    int sum = 0;
    for (auto p : events) {
      if (p.first > eps && p.second < n) {
        sum += points[p.second].degree - 1;
        side[p.second] = true;
      }
    }
    for (auto p : events) {
      if (sum <= -1 && sum >= 1 - max_degree) {
        break;
      }
      if (p.second < n) {
        sum += points[p.second].degree - 1;
        side[p.second] = true;
      } else {
        sum -= points[p.second - n].degree - 1;
        side[p.second - n] = false;
      }
    }
    vector<point_t> left, right;
    for (int i = 0; i < n; ++i) {
      if (side[i]) {
        left.push_back(points[i]);
      } else {
        right.push_back(points[i]);
      }
    }
    left.emplace_back(points[n].x, points[n].y, points[n].id, -sum);
    right.emplace_back(points[n].x, points[n].y, points[n].id,
                       sum + max_degree);
    solve(left);
    solve(right);
  }
}
