  double l2 = dist(x2, y2, z2, 0, 0, h);
  if (fabs(l1) < eps || fabs(l2) < eps) {
    return l1 + l2;
  }
  double coef = l2 / l1;
  double xn = x1 * coef;
  double yn = y1 * coef;
  double zn = h + (z1 - h) * coef;
  double cr = sqrt(l2 * l2 - (h - z2) * (h - z2));
  double ang = acos((xn * x2 + yn * y2) / (cr * cr));
