template<typename T = int64_t>
struct fraction: pair<T, T> {  
    template<typename T2 = int>      
    fraction(T2 x = 0, T2 y = 1) {          
        this->first = x;
        this->second = y;
        norm(this->first, this->second);
    }
    pair<T, T> to_pair() const {
        return *this;
    }
    void norm(T &x, T &y) const {
        T g = gcd(x, y);
        x /= g;
        y /= g;
    }
    fraction operator+=(const fraction &that) {
        *this = *this + that;
        return *this;
    }
    fraction operator+(const fraction &that) const {
        T x = (int64_t)this->first * that.second + this->second * that.first;
        T y = (int64_t)this->second * that.second;
        norm(x, y);
        return {x, y};
    }
    fraction operator-=(const fraction &that) {
        *this = *this - that;
        return *this;
    }
    fraction operator-(const fraction &that) const {
        T x = (int64_t)this->first * that.second - this->second * that.first;
        T y = (int64_t)this->second * that.second;
        norm(x, y);
        return {x, y};
    }
    fraction operator*=(const fraction &that) {
        *this = *this * that;
        return *this;
    }
    fraction operator*(const fraction &that) const {
        T x = (int64_t)this->first * that.first;
        T y = (int64_t)this->second * that.second;
        norm(x, y);
        return {x, y};
    }
    fraction operator/=(const fraction &that) {
        *this = *this / that;
        return *this;
    }
    fraction operator/(const fraction &that) const {
        T x = (int64_t)this->first * that.second;
        T y = (int64_t)this->second * that.first;
        norm(x, y);
        return {x, y};
    }
};
template<typename T>
struct graph: vector<vector<T>> {
    void add(int u, T v) {
        if (u >= this->size()) {
            this->resize(u + 1);
        }
        this->at(u).push_back(v);
    }    
};
#define double long double
void solve() {
    int n;
    cin >> n;
    vector<pair<pair<double, double>, int>> raw(n);
    for (int i = 0; i < n; i++) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        double x = 1.0 * a / b;
        double y = 1.0 * c / d;
        raw[i] = {{x, y}, i};
    }
    int tot = 0;    
    vector<double> arr;
    for (auto &&[v, id]: raw) {
        auto &&[x, y] = v;
        arr.push_back((x + 1) / y);
        arr.push_back(x / (y + 1));
    }        
    sort(arr.begin(), arr.end());
    map<double, int> encoder;
    encoder[arr[0]] = tot;
    tot++;
    for (int i = 1; i < arr.size(); i++) {
        if (arr[i] - arr[i - 1] < 1e-15) {
            encoder[arr[i]] = tot - 1;
        } else {
            encoder[arr[i]] = tot;
            tot++;
        }
    }
    graph<pair<int, int>> g;
    for (auto &&[v, id]: raw) {
        auto &&[x, y] = v;
        g.add(encoder[(x + 1) / y], {encoder[x / (y + 1)], id});
        g.add(encoder[x / (y + 1)], {encoder[(x + 1) / y], id});
    }
    vector<int> vis(tot);
    vector<bool> vis_e(n);
    vector<pair<int, int>> ans;
    function<int(int)> go = [&](int u) {
        vis[u] = 1;
        vector<int> edges;
        for (auto &&[v, id]: g[u]) {
            if (vis_e[id] || vis[v] == 2) {
                continue;
            }
            vis_e[id] = 1;
            if (vis[v]) {
                edges.push_back(id);
                continue;
            }
            int temp = go(v);
            if (temp == -1) {
                edges.push_back(id);
            } else {
                ans.push_back({temp, id});
            }
        }
        for (int i = 1; i < edges.size(); i += 2) {
            ans.push_back({edges[i - 1], edges[i]});
        }
        vis[u] = 2;
        if (edges.size() & 1) {
            return edges.back();
        } 
        return -1;
    };
    for (int i = 0; i < tot; i++) {
        if (!vis[i]) {
            go(i);
        }
    }    
    cout << ans.size() << endl;
    for (auto &&[a, b]: ans) {
        cout << a + 1 << " " << b + 1 << endl;
    }
}


