    tr.a = line.start + (line.dir0 * ansmid);
    tr.b = line.start + (line.dir1 * ansmid);
    tr.c = line.start;
    if (InTriangle(p, tr))
      ansmax = ansmid;
    else
      ansmin = ansmid;
  }
  return ansmax;
}
