      int nm = 0, pos = -1;
      for (int j(0); j < (m); j++)
        if (fabs(system[j][i]) > eps) nm++, pos = j;
      if (nm == 1 && fabs(system[pos][i] - 1) < eps && base[pos] == -1)
        base[pos] = i;
    }
    for (int i(0); i < (m); i++)
      if (base[i] == -1) {
        N++;
        c.push_back(SM_INF);
        for (int j(0); j < (m); j++) system[j].push_back(j == i ? 1 : 0);
        base[i] = N - 1;
      }
