    while (1) {
      int pos = -1, row = -1;
      for (int i(0); i < (N); i++)
        if (c[i] < -eps && (pos == -1 || c[i] < c[pos])) pos = i;
      if (pos == -1) break;
      double min_teta = 0;
      for (int i(0); i < (m); i++)
        if (system[i][pos] > eps &&
            (row == -1 || min_teta > b[i] / system[i][pos]))
          row = i, min_teta = b[i] / system[i][pos];
