      v.push_back(make_pair(pi, -1));
      for (j = 0; j < n; j++)
        if (i != j) {
          point q = c[j].p.sub(c[i].p);
          double ab = q.len(), ac = c[i].r, bc = c[j].r;
          if (dblcmp(ab + ac - bc) <= 0) {
            v.push_back(make_pair(-pi, 1));
            v.push_back(make_pair(pi, -1));
