int check(int p, int q) {
  long long R = P(r[p] + r[q]), R2 = P(r[p] - r[q]);
  long long L = P(x[p] - x[q]) + P(y[p] - y[q]);
  if (L == R || L == R2) return 1;
  if (L > R || L < R2) return 0;
  return 2;
}
int check2(int p, int q) {
  long long R = P(r[p] + r[q]), R2 = P(r[p] - r[q]);
  long long L = P(x[p] - x[q]) + P(y[p] - y[q]);
  if (L == R) return 1;
  if (L == R2) return 2;
  if (L > R) return 3;
  if (L < R2) return 4;
  return 0;
}
void get(int p, int q) {
  if (check2(p, q) == 1) {
    pair<long long, long long> a;
    a.first = (long long)((x[p] * 1.0 * r[q] * 1.0 + x[q] * 1.0 * r[p] * 1.0) /
