                          0.3);
    a.second = (long long)((y[p] * 1.0 * r[q] * 1.0 + y[q] * 1.0 * r[p] * 1.0) /
                               (r[p] * 1.0 + r[q] * 1.0) +
                           0.3);
    s[0].insert(a);
    s[p].insert(a);
    s[q].insert(a);
    return;
  }
  if (check2(p, q) == 2) {
    if (r[p] < r[q]) swap(p, q);
    pair<long long, long long> a;
    a.first = (long long)((x[q] * 1.0 * r[p] * 1.0 - x[p] * 1.0 * r[q] * 1.0) /
                              (r[p] * 1.0 - r[q] * 1.0) +
                          0.3);
    a.second = (long long)((y[q] * 1.0 * r[p] * 1.0 - y[p] * 1.0 * r[q] * 1.0) /
