  long double dM = c1.r + c2.r;
  if (less(d, dm) || less(dM, d)) {
    return std::vector<vt>();
  }
  long double d1 = 0.5 * (d + (c1.r * c1.r - c2.r * c2.r) / d);
  if (is_eq(std::abs(d1), c1.r)) {
