    if (sumN % 2 == 1 && i == half - 1) cnt--;
    for (int j = 0; j <= n[0]; ++j) {
      for (int k = 0; k <= n[1]; ++k) {
        if (dp[i][j][k] > -0.5) {
          if (cnt == 0) {
            dp[i + 1][j][k] = max(dp[i + 1][j][k], dp[i][j][k]);
          }
          if (cnt == 1) {
            if (j)
              dp[i + 1][j - 1][k] =
                  max(dp[i + 1][j - 1][k], dp[i][j][k] + calc(1, 0, i));
            if (k)
              dp[i + 1][j][k - 1] =
                  max(dp[i + 1][j][k - 1], dp[i][j][k] + calc(0, 1, i));
          }
          if (cnt == 2) {
            if (j && k)
              dp[i + 1][j - 1][k - 1] =
                  max(dp[i + 1][j - 1][k - 1], dp[i][j][k] + calc(1, 1, i));
            if (j >= 2)
              dp[i + 1][j - 2][k] =
                  max(dp[i + 1][j - 2][k], dp[i][j][k] + calc(2, 0, i));
            if (k >= 2)
              dp[i + 1][j][k - 2] =
                  max(dp[i + 1][j][k - 2], dp[i][j][k] + calc(0, 2, i));
          }
        }
      }
    }
  }
  return dp[half][0][0];
}
