vector<point> cccross(point O1, double r1, point O2, double r2) {
  double d = dist(O1, O2);
  double t = (d * d + r1 * r1 - r2 * r2) / 2.0 / d / d;
  double fx = O1.x + (O2.x - O1.x) * t, fy = O1.y + (O2.y - O1.y) * t;
