def hill_climbing(circles):
    def diff(x):
        d = []
        for y, ry in circles:
            d.append(abs(x - y) / ry)
        ans = 0
        for i in range(3):
            ans += (d[i] - d[(i+1)%3]) ** 2
        return ans

    x = 0
    s = 1
    for y, _ in circles:
        x += y / 3
    while s > 1e-6:
        d0 = diff(x)
        if d0 > diff(x + s): x += s
        elif d0 > diff(x - s): x -= s
        elif d0 > diff(x + s*1j): x += s*1j
        elif d0 > diff(x - s*1j): x -= s*1j
        else: s *= 0.7
    return x if diff(x) < 1e-5 else None


