double f(double ox, double oy) {
  for (int i = 0; i < 3; ++i) {
    a[i] =
        sqrt(((x[i] - ox) * (x[i] - ox)) + ((y[i] - oy) * (y[i] - oy))) / r[i];
  }
  double sum = 0;
  for (int i = 0; i < 3; ++i) {
    sum += ((a[i] - a[(i + 1) % 3]) * (a[i] - a[(i + 1) % 3]));
  }
  return sum;
