    ret.y = y - other.y;
    return ret;
  }
};
struct Segment {
  Point a, b;
  bool operator<(const Segment other) const {
    if (fabs(a.y - other.a.y) > error)
      return a.y + error < other.a.y;
    else
      return b.y + error < other.b.y;
  }
};
