bool Equals(double a, double b) { return fabs(a - b) < error; }
bool Bigger(double a, double b) { return a > b + error; }
bool Smaller(double a, double b) { return a + error < b; }
bool BiggerEquals(double a, double b) { return Bigger(a, b) || Equals(a, b); }
bool SmallerEquals(double a, double b) { return Smaller(a, b) || Equals(a, b); }
Point MakePoint(double x, double y) {
  Point ret;
  ret.x = x;
  ret.y = y;
  return ret;
}
Segment MakeSegment(double x0, double y0, double x1, double y1) {
  Segment ret;
  ret.a = MakePoint(x0, y0);
  ret.b = MakePoint(x1, y1);
  return ret;
}
Region MakeRegion(bool isLine, double x0, double y0, double x1, double y1,
                  double x2 = 0, double y2 = 0, double x3 = 0, double y3 = 0) {
  Region ret;
  ret.isLine = isLine;
  ret.top = MakeSegment(x0, y0, x1, y1);
  ret.bot = MakeSegment(x2, y2, x3, y3);
  if (isLine) ret.bot = ret.top;
