double CrossProduct(Point p0, Point p1) { return p0.x * p1.y - p1.x * p0.y; }
bool Intersect(Segment s0, Segment s1, Point& retp) {
  double D;
  D = CrossProduct(s0.b - s0.a, s1.b) - CrossProduct(s0.b - s0.a, s1.a);
  if (Bigger(CrossProduct(s0.b - s0.a, s1.a - s0.a) *
                 CrossProduct(s0.b - s0.a, s1.b - s0.a),
             0) ||
      Bigger(CrossProduct(s1.b - s1.a, s0.a - s1.a) *
                 CrossProduct(s1.b - s1.a, s0.b - s1.a),
             0))
    return false;
  if (Equals(D, 0)) return false;
  retp.x = ((s0.b.x - s0.a.x) * CrossProduct(s1.a, s1.b) -
            (s1.b.x - s1.a.x) * CrossProduct(s0.a, s0.b)) /
           D;
  retp.y = ((s0.b.y - s0.a.y) * CrossProduct(s1.a, s1.b) -
            (s1.b.y - s1.a.y) * CrossProduct(s0.a, s0.b)) /
           D;
  return true;
}
Point GetPointAtSegByX(Segment s, double x) {
  Point ret;
