  if (Equals(s.a.x, s.b.x)) {
    ret.x = ret.y = -1;
    return ret;
  }
  ret.x = x;
  ret.y = (x - s.a.x) / (s.b.x - s.a.x) * (s.b.y - s.a.y) + s.a.y;
