            SmallerEquals(min(s0.a.y, s0.b.y), max(s1.a.y, s1.b.y)) &&
            BiggerEquals(max(s0.a.y, s0.b.y), min(s1.a.y, s1.b.y)));
  } else {
    return (!Equals(s1.a.x, s1.b.x) &&
            SmallerEquals(min(s0.a.x, s0.b.x), max(s1.a.x, s1.b.x)) &&
            BiggerEquals(max(s0.a.x, s0.b.x), min(s1.a.x, s1.b.x)) &&
            Equals(GetPointAtSegByX(s0, s1.a.x).y, s1.a.y) &&
            Equals(GetPointAtSegByX(s0, s1.b.x).y, s1.b.y));
