bool CutSegByIntv(Segment s, double x0, double x1, Segment& outputSeg) {
  if (Bigger(s.a.x, s.b.x)) swap(s.a, s.b);
  if (Equals(s.a.x, s.b.x) || BiggerEquals(x0, s.b.x) ||
      SmallerEquals(x1, s.a.x))
    return false;
  else {
    outputSeg.a = GetPointAtSegByX(s, max(s.a.x, x0));
    outputSeg.b = GetPointAtSegByX(s, min(s.b.x, x1));
    return true;
  }
}
bool IsTouched(Region r0, Region r1) {
  if (r0.isLine) {
    return Equals(r0.top.b.y, r1.top.a.y);
  } else {
    Segment touchSeg;
    touchSeg.a.x = touchSeg.b.x = r0.bot.b.x;
    touchSeg.a.y = max(r0.top.b.y, r1.top.a.y);
    touchSeg.b.y = min(r0.bot.b.y, r1.bot.a.y);
    if (BiggerEquals(touchSeg.a.y, touchSeg.b.y))
      return false;
    else {
      bool updated = true;
      while (updated) {
        updated = false;
        for (int i = 0; i < n; i++)
          if (Equals(sa[i].a.x, sa[i].b.x) && Equals(sa[i].a.x, touchSeg.a.x) &&
              SmallerEquals(min(sa[i].a.y, sa[i].b.y), touchSeg.a.y) &&
              Smaller(touchSeg.a.y, max(sa[i].a.y, sa[i].b.y))) {
            updated = true;
            touchSeg.a.y = max(sa[i].a.y, sa[i].b.y);
            break;
          }
      }
      return Smaller(touchSeg.a.y, touchSeg.b.y);
    }
  }
}
bool isLineRegTouched(Region line, Region reg) {
  if (reg.isLine) swap(line, reg);
  if (Equals(line.top.a.x, line.top.b.x)) {
    return (Equals(line.top.a.x, reg.top.a.x) &&
                SmallerEquals(reg.top.a.y, max(line.top.a.y, line.top.b.y)) &&
                BiggerEquals(reg.bot.a.y, min(line.top.a.y, line.top.b.y)) ||
            Equals(line.top.a.x, reg.top.b.x) &&
                SmallerEquals(reg.top.b.y, max(line.top.a.y, line.top.b.y)) &&
                BiggerEquals(reg.bot.b.y, min(line.top.a.y, line.top.b.y)));
  } else if (SmallerEquals(reg.top.a.x, max(line.top.a.x, line.top.b.x)) &&
             BiggerEquals(reg.top.b.x, min(line.top.a.x, line.top.b.x))) {
    return (
        Equals(GetPointAtSegByX(line.top, reg.top.a.x).y, reg.top.a.y) &&
            Equals(GetPointAtSegByX(line.top, reg.top.b.x).y, reg.top.b.y) ||
        Equals(GetPointAtSegByX(line.top, reg.bot.a.x).y, reg.bot.a.y) &&
            Equals(GetPointAtSegByX(line.top, reg.bot.b.x).y, reg.bot.b.y));
  } else
