}
bool InRegion(Point p, Region r) {
  if (r.isLine) {
    Segment seg = r.top;
    if (Bigger(seg.a.x, seg.b.x)) swap(seg.a, seg.b);
    if (Equals(seg.a.x, seg.b.x)) {
      if (Equals(p.x, seg.a.x) && SmallerEquals(min(seg.a.y, seg.b.y), p.y) &&
          SmallerEquals(p.y, max(seg.a.y, seg.b.y)))
        return true;
      else
        return false;
    } else {
      if (SmallerEquals(seg.a.x, p.x) && SmallerEquals(p.x, seg.b.x) &&
          Equals(GetPointAtSegByX(seg, p.x).y, p.y))
        return true;
      else
        return false;
    }
  } else
    return SmallerEquals(r.top.a.x, p.x) && SmallerEquals(p.x, r.top.b.x) &&
           SmallerEquals(GetPointAtSegByX(r.top, p.x).y, p.y) &&
           SmallerEquals(p.y, GetPointAtSegByX(r.bot, p.x).y);
}
double CalcArea(Region r) {
  if (r.isLine)
    return 0;
  else
    return (r.bot.a.y - r.top.a.y + r.bot.b.y - r.top.b.y) *
           (r.top.b.x - r.top.a.x) / 2;
}
void AddEdge(int a, int b) {
  gra[a].push_back(b);
  gra[b].push_back(a);
