}
void RelateRegionWithVerticalLine(Region r, int index) {
  if (r.isLine) r.bot = r.top, r.isLine = false;
  for (int i = 0; i < vsan; i++)
    if (isLineRegTouched(ra[i], r)) AddEdge(i, index);
