  for (const vec2l& point : points) {
    if (point.x < left.x || (point.x == left.x && point.y < left.y)) {
      left = point;
    }
    if (point.x > right.x || (point.x == right.x && point.y > right.y)) {
      right = point;
    }
  }
  if (left.x == right.x) {
    hull.push_back(left);
    if (left.y != right.y) {
      hull.push_back(right);
