def qsort(A, left, right):
    while left < right:
        q = partition(A, left, right)
        if (q - 1) - left < right - (q + 1):
            qsort(A, left, q-1)
            left = q + 1
        else:
            qsort(A, q+1, right)
            right = q - 1


def partition(A, left, right):
    q = A[right]
    i = left - 1
    for j in range(left, right):
        if abs(A[j]) < abs(q):
            i += 1
            A[i], A[j] = A[j], A[i]
    A[i+1], A[right] = A[right], A[i+1]
    return i+1


