}
bool outsidewindow(const P &a) {
  return a.x < wlx || a.x > whx || a.y < wly || a.y > why;
}
int solve() {
  swap(wly, why);
  wlx *= 3, wly *= 3, whx *= 3, why *= 3;
  ++wlx, ++wly, --whx, --why;
  for (int i = (0); i < (n); ++i) p[i].x *= 3, p[i].y *= 3;
  whor = whx - wlx, wver = why - wly;
  int outidx = 0;
  while (outidx < n && !outsidewindow(p[outidx])) ++outidx;
  if (outidx >= n) return 1;
  ninter = 0;
  for (int i = (0); i < (n); ++i) {
    int a = (outidx + i) % n, b = (outidx + i + 1) % n;
    addinter(p[a], p[b]);
  }
  assert(ninter % 2 == 0);
  if (ninter == 0) return insidepolygon(P(wlx, wly)) ? 1 : 0;
  nall = 0;
  for (int i = (0); i < (ninter); ++i) all[nall++] = inter[i];
  sort(all, all + nall);
  nall = unique(all, all + nall) - all;
  assert(nall == ninter);
  for (int i = (0); i < (ninter); ++i)
    inter[i] = lower_bound(all, all + nall, inter[i]) - all;
  for (int i = (0); i < (ninter); ++i) nxt[inter[i]] = inter[(i + 1) % n];
  int ret = 0;
