struct Interval {
  double val;
  double sz;
  Interval() {}
  Interval(int x) {
    val = x;
    sz = 1;
  }
  Interval(double x, double y) {
    val = x;
    sz = y;
  }
  void mix(Interval i) {
    double water = val * sz + (i.val * i.sz);
    double nsz = sz + i.sz;
    val = water / nsz;
    sz = nsz;
  }
};
