        t2 = b.tim + (double)Abs(u1 - b.fr) / b.spd;
      else
        t1 = a.tim + (double)Abs(a.fr - v1) / a.spd,
        t2 = b.tim + (double)Abs(b.fr - v1) / b.spd;
      if (a.spd == b.spd) {
