const int maxn = 100005;
int ready[2 * maxn];
vector<point> tree[2 * maxn];
void fix(int x) {
  if (!ready[2 * x]) fix(2 * x);
  if (!ready[2 * x + 1]) fix(2 * x + 1);
  vector<point> tmp(tree[2 * x].size() + tree[2 * x + 1].size());
  merge(begin(tree[2 * x]), end(tree[2 * x]), begin(tree[2 * x + 1]),
        end(tree[2 * x + 1]), begin(tmp));
  for (point p : tmp) {
    while (tree[x].size() > 1) {
      point a = tree[x][tree[x].size() - 2];
      point b = tree[x][tree[x].size() - 1];
      if (1. * (b.second - a.second) / (b.first - a.first) <
          1. * (p.second - b.second) / (p.first - b.first))
        break;
      tree[x].pop_back();
    }
    tree[x].push_back(p);
  }
  ready[x] = 1;
}
ll bsearch(int lo, int hi, function<ll(int)> f) {
  while (lo < hi) {
    int md = (lo + hi) / 2;
    if (f(md) > f(md + 1)) {
      lo = md + 1;
    } else {
      hi = md;
    }
  }
  return f(lo);
}
ll calc(int x, ll a) {
  if (!ready[x]) fix(x);
  return bsearch(0, tree[x].size() - 1, [&](int y) {
    return tree[x][y].first * a + tree[x][y].second;
  });
}
ll get(int l, int r, ll a) {
  ll ret = 1e18;
  for (l += maxn, r += maxn; l < r; l /= 2, r /= 2) {
    if (l & 1) ret = min(ret, calc(l++, a));
    if (r & 1) ret = min(ret, calc(--r, a));
  }
  return ret;
}
