namespace Segement {
const int maxP = maxN << 3;
bool used[maxN] = {false};
int vis[maxP] = {0};
bool clear[maxP] = {false};
struct node {
  long long k, b;
  node(long long _k = 0, long long _b = 0) : k(_k), b(_b) {}
} t[maxP];
void pushdown(int rt) {
  if (clear[rt]) {
    clear[rt << 1] = true;
    clear[rt << 1 | 1] = true;
    vis[rt << 1] = 0;
    vis[rt << 1 | 1] = 0;
    clear[rt] = false;
  }
}
void add(int rt, int l, int r, node nex, int id) {
  if (l > r) return;
  if (!vis[rt]) {
    t[rt] = nex;
    vis[rt] = id;
    used[id] = true;
    return;
  }
  pushdown(rt);
  int mid = (l + r) / 2;
  long long v1, v2;
  if (t[rt].k > nex.k) {
    v1 = t[rt].k * mid + t[rt].b;
    v2 = nex.k * mid + nex.b;
    if (v2 <= v1) {
      int nex_id = vis[rt];
      used[nex_id] = false;
      vis[rt] = id;
      used[id] = true;
      swap(t[rt], nex);
      add(rt << 1, l, mid - 1, nex, nex_id);
    } else {
      add(rt << 1 | 1, mid + 1, r, nex, id);
    }
  } else if (t[rt].k < nex.k) {
    v1 = t[rt].k * mid + t[rt].b;
    v2 = nex.k * mid + nex.b;
    if (v2 <= v1) {
      int nex_id = vis[rt];
      used[nex_id] = false;
      vis[rt] = id;
      used[id] = true;
      swap(t[rt], nex);
      add(rt << 1 | 1, mid + 1, r, nex, nex_id);
    } else {
      add(rt << 1, l, mid - 1, nex, id);
    }
  } else {
    if (t[rt].b > nex.b) {
      used[vis[rt]] = false;
      vis[rt] = id;
      used[id] = true;
      t[rt] = nex;
    }
  }
}
long long query(int rt, int l, int r, int qx) {
  if (l > r) return 0x3f3f3f3f3f3f3f3f;
  long long ans = 0x3f3f3f3f3f3f3f3f;
  if (vis[rt]) ans = t[rt].k * qx + t[rt].b;
  pushdown(rt);
  int mid = (l + r) / 2;
  if (qx < mid)
    ans = min(ans, query(rt << 1, l, mid - 1, qx));
  else if (qx > mid)
    ans = min(ans, query(rt << 1 | 1, mid + 1, r, qx));
  return ans;
}
}  // namespace Segement
