void dfs_2(int u, int fa, bool save) {
  for (int i = head[u], v; ~i; i = edge[i].nex) {
    v = edge[i].to;
    if (v == fa || v == wson[u]) continue;
    dfs_2(v, u, false);
  }
  if (wson[u]) dfs_2(wson[u], u, true);
  for (int i = head[u], v; ~i; i = edge[i].nex) {
    v = edge[i].to;
    if (v == fa || v == wson[u]) continue;
    push_In(v, u);
  }
  if (leafe[u]) {
    c[u] = 0;
    if (save) add(1, -_UP, _UP, node(b[u], c[u]), u);
  } else {
    c[u] = query(1, -_UP, _UP, a[u]);
    if (save)
      add(1, -_UP, _UP, node(b[u], c[u]), u);
    else {
      clear[1] = true;
      vis[1] = 0;
    }
  }
}
