      qrys[bak].tar = 0, qrys[bak].coef = A[i];
    }
    for (int i = 1; i <= Q; ++i) {
      vec x = X * ts[i] + qs[i], y = Y * ts[i] + qs[i];
      ++bak, tv[bak] = std::pair<vec, int>(x - ori, bak);
      td[bak] = std::pair<long long, int>(get(x - ori, D), bak);
      qrys[bak].tar = i, qrys[bak].coef = 1;
      ++bak, tv[bak] = std::pair<vec, int>(y - ori, bak);
      td[bak] = std::pair<long long, int>(get(y - ori, D), bak);
      qrys[bak].tar = i, qrys[bak].coef = -1;
    }
    int vsz = discretization(tv, bak, nv);
    bitsz = discretization(td, bak, nd);
    for (int i = 1; i <= bak; ++i) {
      qrys[i].pol = nv[i];
      qrys[i].dis = nd[i];
    }
    for (int i = 1; i <= bak; ++i)
