        if (rec[T][u] == 1) --qrys[i].pol;
        if (qrys[i].coef == -1 && close[T][u]) qrys[i].pol += rec[T][u];
      }
    std::sort(qrys + 1, qrys + 1 + bak);
    int L = 1, R = 1;
    for (int i = 1; i <= vsz; ++i) {
      while (L <= bak && qrys[L].pol < i) ++L;
      while (R <= bak && qrys[R].pol <= i) ++R;
      for (int j = L; j < R; ++j)
        if (qrys[j].tar == 0) add(qrys[j].dis, qrys[j].coef);
      for (int j = L; j < R; ++j)
        if (qrys[j].tar > 0) {
          long long a = qry(qrys[j].dis), b = qry(qrys[j].dis - 1);
          tmp[qrys[j].tar] += a * qrys[j].coef;
          col[qrys[j].tar] += (a - b) * qrys[j].coef;
        }
