    }
    for (int i = 1; i <= Q; ++i) {
      tmp[i] = std::abs(tmp[i]);
      col[i] = std::abs(col[i]);
      if (rec[T][i] == -1) tmp[i] -= col[i];
      ansl[i] += tmp[i] * rec[T][i];
      tmp[i] = col[i] = 0;
    }
