double GetAngle(const double x, const double y) {
  if (x == 0) {
    if (y > 0)
      return pi / 2;
    else
      return pi / 2 * 3;
  }
  if (x > 0) {
    if (y < 0)
      return atan(y / x) + pi * 2;
    else
      return atan(y / x);
  } else {
    return atan(y / x) + pi;
  }
}
double GetAngle(const Point& p) { return GetAngle(p.x, p.y); }
bool In(const Point& cen, const Point& a, const Point& b) {
