double cross(int x, int y) {
  return (double)(C[x] - C[y]) / (Slope[y] - Slope[x]);
}
void AddLine(long long p, long long q) {
  Slope[++hsz] = p;
  C[hsz] = q;
  while (hsz >= 3 && cross(hsz - 2, hsz - 1) > cross(hsz - 2, hsz)) {
    --hsz;
    Slope[hsz] = Slope[hsz + 1];
    C[hsz] = C[hsz + 1];
  }
