    mid = (lw + hi) / 2;
    midd = min(hsz, mid + 1);
    if (get(mid, x) <= get(midd, x)) {
      hi = mid - 1;
      ans = get(mid, x);
    } else {
      lw = midd + 1;
      ans = get(midd, x);
    }
  }
  return ans;
}
