  auto tmp = calc(lazy[v]);
  lazy[v].clear();
  for (auto it : tmp) {
    add_line(lazy[v], it);
  }
  if (tl != tr) {
    int mid = (tl + tr) / 2;
    traverse(v + v, tl, mid);
    traverse(v + v + 1, mid + 1, tr);
  }
}
