    to_process.push_back(Q[i].x);
    if (Q[i].x < l) cnt[Q[Q[i].x].id]--;
  }
  hull_and_solve(l, r);
  for (i = l; i <= r; i++)
    if (Q[i].tp == 2)
      if (Q[i].x < l) cnt[Q[Q[i].x].id]++;
  for (i = l; i <= r; i++) {
