  return make_pair(a.x, a.y) < make_pair(b.x, b.y);
}
inline bool scmp(const point &a, const point &b) {
  double cross = ((point)a - o) * ((point)b - o);
  if (fabs(cross) <= 1e-20) return o.dis(a) < o.dis(b);
  return cross < 1e-20;
}
