void add(int a, int b, int x, int l = 1, int h = 1e4 + 2, int p = 1) {
  if (a == l && b == h) {
    dp[p] += x;
    return;
  }
  int m = (l + h) / 2;
  if (b <= m) {
    add(a, b, x, l, m, 2 * p);
  } else if (a > m) {
    add(a, b, x, m + 1, h, 2 * p + 1);
  } else {
    add(m + 1, b, x, m + 1, h, 2 * p + 1);
    add(a, m, x, l, m, 2 * p);
  }
  dp[p] = dp[2 * p] + dp[2 * p + 1];
}
int cal(int a, int b, int x = 0, int l = 1, int h = 1e4 + 2, int p = 1) {
  if (a == l && b == h) {
    return dp[p];
