  P() : x(0), y(0) {}
  P(long long xx, long long yy) : x(xx), y(yy) {}
  int quadrant() const {
    if (x >= 0 && y > 0)
      return 0;
    else if (x > 0 && y <= 0)
      return 1;
    else if (x <= 0 && y < 0)
      return 2;
    else
      return 3;
  }
  long long operator^(P p) const { return x * p.y - y * p.x; }
  long long operator*(P p) const { return x * p.x + y * p.y; }
  long long szsq() { return x * x + y * y; }
  bool operator<(const P &p) const {
    if (quadrant() != p.quadrant())
      return quadrant() < p.quadrant();
    else
      return ((*this) ^ p) < 0;
  }
};
long long sign(long long a) {
