  assert(b != 0 && d != 0);
  if (b < 0) {
    a *= -1;
    b *= -1;
  }
  if (d < 0) {
    c *= -1;
    d *= -1;
  }
  if (sign(a) != sign(c)) return sign(a) < sign(c);
  bool reverse = false;
  if (a < 0) {
    reverse = true;
    a *= -1;
    c *= -1;
  }
  if (a / b != c / d)
    return ((a / b < c / d) ^ reverse);
  else if (!reverse) {
    if (c % d == 0)
      return false;
    else if (a % b == 0)
      return true;
    else
      return less(d, c % d, b, a % b);
  } else {
    if (a % b == 0)
      return false;
    else if (c % d == 0)
      return true;
    else
      return less(b, a % b, d, c % d);
  }
}
