				for(int i = 0; i <= N-2; i++){
					Y[i] &= X[i+1] - X[i];		
					if(i >= 1) Y[i] &= Y[i-1] + Z[i-1];		
					X[i+1] &= X[i] + Y[i];
					if(i <= N-3) Z[i] &= Y[i+1] - Y[i];
				}
				for(int i = N-2; i >= 0; i--){
					Y[i] &= X[i+1] - X[i];		
					if(i <= N-3) Y[i] &= Y[i+1] - Z[i];		
					X[i] &= X[i+1] - Y[i];
					if(i >= 1) Z[i-1] &= Y[i] - Y[i-1];
