bool solve() {
	Hull lo;
	Hull hi;


	auto empty = [&]() {
		return lo.q.empty() || hi.q.empty();
	};
	auto clear = [&]() {
		lo.q.clear();
		hi.q.clear();
	};
	auto cutbelow = [&](int y) {
		if (empty()) return;
		if (lo.ymax() < y) return clear();
		lo.cutbelow(y);
		hi.cutbelow(y);
		lo.prepend(hi.first());
	};
	auto cutabove = [&](int y) {
		if (empty()) return;
		if (lo.ymin() > y) return clear();
		lo.cutabove(y);
		hi.cutabove(y);
		hi.append(lo.last());
	};
	auto cutleft = [&](int x) {
		if (empty()) return;
		if (lo.xmax() < x) return clear();
		lo.cutleft(x);
		hi.cutleft(x);
		hi.prepend(lo.first());
	};
	auto cutright = [&](int x) {
		if (empty()) return;
		if (lo.xmin() > x) return clear();
		lo.cutright(x);
		hi.cutright(x);
		lo.append(hi.last());
	};
	auto transform = [&]() {
		if (empty()) return;
		lo.transform();
		hi.transform();
	};
	auto translate = [&](int lz,int hz) {
		if (empty()) return;
		lo.translate(lz);
		hi.translate(hz);
		lo.append(hi.last());
		hi.prepend(lo.first());
	};

	P llo(xlo[1], xlo[1] - xhi[0]);
	P rlo(xhi[1], xhi[1] - xhi[0]);
	P lhi(xlo[1], xlo[1] - xlo[0]);
	P rhi(xhi[1], xhi[1] - xlo[0]);
	lo.append(llo);
	lo.append(rlo);
	lo.append(rhi);
	hi.append(llo);
	hi.append(lhi);
	hi.append(rhi);
	cutbelow(ylo[1]);
	cutabove(yhi[1]);
	//lo.print("loinit");
	//hi.print("hiinit");

	FOR(i, 2, n) {
		transform();
		translate(zlo[i], zhi[i]);
		cutleft(xlo[i]);
		cutright(xhi[i]);
		cutbelow(ylo[i]);
		cutabove(yhi[i]);
	}
	//lo.print("lofinal");
	//hi.print("hifinal");

	return !empty();
}

