    V2 = [[*v, i, 1] for i, v in enumerate(V) if v[0] * v[1] < 0]
    V3 = [[*v, i, 1] for i, v in enumerate(V) if v[0] == 0]
    V4 = [[*v, i, 1] for i, v in enumerate(V) if v[0] != 0 and v[1] == 0]

    V1.sort(reverse=True, key=lambda x: abs(x[0]) + abs(x[1]))
    V2.sort(reverse=True, key=lambda x: abs(x[0]) + abs(x[1]))
    V3.sort(reverse=True, key=lambda x: abs(x[0]) + abs(x[1]))
    V4.sort(reverse=True, key=lambda x: abs(x[0]) + abs(x[1]))

    def f(V):
        sx, sy = 0, 0
        for i, v in enumerate(V):
            if abs(sx + v[0]) + abs(sy + v[1]) < abs(sx - v[0]) + abs(sy - v[1]):
                v[3] = 1
            else:
                v[3] = -1
            sx += v[3]*v[0]
            sy += v[3]*v[1]
        return sx, sy

    SV = [f(V_) for V_ in [V1, V2, V3, V4]]

    S = min([(D(SV, s), s) for s in product([-1, 1], repeat=4)])
    for s, V_ in zip(S[1], [V1, V2, V3, V4]):
        for v in V_:
            v[3] *= s



    V1.extend(V2)
    V1.extend(V3)
    V1.extend(V4)
    V1.sort(key=lambda x: x[2])
    ans = [v[3] for v in V1]

    error_print(D(V, ans) < 1.5e+6)

    return ' '.join(map(str, ans))


