  x[cnt] = x[0];
  y[cnt] = y[0];
  int ncnt = 0;
  for (int i = 0; i < cnt; i++) {
    double z = aa * x[i] + bb * y[i] + cc;
    if (z < eps) {
      xx[ncnt] = x[i];
      yy[ncnt] = y[i];
      ncnt++;
