  if (hull.empty()) return false;
  if (sgn(p.x - hull.begin()->first) < 0 || sgn(p.x - hull.rbegin()->first) > 0)
    return false;
  auto j = hull.upper_bound(p.x), i = prev(j);
  if (sgn(p.x - i->first) == 0) return sgn(p.y - i->second) >= 0;
  return sgn(cross(Point(*j) - Point(*i), p - Point(*i))) >= 0;
