point_t distToLine(point p, point a, point b, point &ret) {
  vec ap = vec(a, p);
  vec ab = vec(a, b);
  point_t u = dot(ap, ab) / norm_sq(ab);
  ret = a + ab * u;
  return dist(p, ret);
}
point_t distToLineSegment(point p, point a, point b, point &ret) {
  vec ap = vec(a, p);
  vec ab = vec(a, b);
  point_t u = dot(ap, ab) / norm_sq(ab);
  if (u < 0.0) {
    ret = a;
    return dist(p, a);
  } else if (u > 1.0) {
    ret = b;
    return dist(p, b);
  }
  return distToLine(p, a, b, ret);
}
