  if (areParallel(l1, l2)) return false;
  ret.x = (l2.b * l1.c - l1.b * l2.c) / (l2.a * l1.b - l1.a * l2.b);
  if (fabs(l1.b) > EPS)
    ret.y = -(l1.a * ret.x + l1.c);
  else
