bool isConvex(const vector<point> &P) {
  int sz = P.size();
  if (sz <= 3) return false;
  bool isLeft = (ccw(P[0], P[1], P[2]) > 0);
  for (int i = 1; i + 1 < sz; i++)
    if (ccw(P[i], P[i + 1], (i + 2 == sz ? P[1] : P[i + 2])) != isLeft)
      return false;
  return true;
