bool inPolygon(point pt, const vector<point> &P) {
  if (P.size() == 0) return false;
  point_t sum = 0;
  for (int i = 0; i + 1 < P.size(); i++)
    if (ccw(pt, P[i], P[i + 1]) > 0)
      sum += angle(P[i], pt, P[i + 1]);
    else
      sum -= angle(P[i], pt, P[i + 1]);
  if (fabs(sum - 2 * PI) < EPS) return true;
  if (fabs(sum + 2 * PI) < EPS) return true;
  return false;
}
