  int mid = l + r >> 1;
  closestHelp(a, l, mid, gmin);
  closestHelp(a, mid, r, gmin);
  vector<point> ord;
  int sweep = 0;
  for (int i = l, j = mid; i < mid && j < r;) {
    int id = (i < mid && (a[i].y < a[j].y || j < r) ? i++ : j++);
    while (sweep < ord.size() && a[id].y - ord[sweep].y >= gmin) sweep++;
    for (int i = sweep; i < ord.size(); i++)
