  long long s0 =
      (x.p[1].first - x.p[0].first) * (x.p[1].second + x.p[0].second);
  long long s1 =
      (x.p[2].first - x.p[1].first) * (x.p[2].second + x.p[1].second);
  long long s2 =
      (x.p[3].first - x.p[2].first) * (x.p[3].second + x.p[2].second);
  long long s3 =
      (x.p[0].first - x.p[3].first) * (x.p[0].second + x.p[3].second);
