#include <bits/stdc++.h>
using namespace std;
const double ee = 1e-15;
const double EPS = 1e-15;
struct PT {
  double x, y;
  double length() { return sqrt(x * x + y * y); }
  int normalize() {
    double l = length();
    if (fabs(l) < EPS) return -1;
    x /= l;
    y /= l;
    return 0;
  }
  PT operator-(PT a) {
    PT r;
    r.x = x - a.x;
    r.y = y - a.y;
    return r;
  }
  PT operator+(PT a) {
    PT r;
    r.x = x + a.x;
    r.y = y + a.y;
    return r;
  }
  PT operator*(double sc) {
    PT r;
    r.x = x * sc;
    r.y = y * sc;
    return r;
  }
};
double dist(PT& a, PT& b) {
  return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}
double trap(PT a, PT b) { return (0.5 * (b.x - a.x) * (b.y + a.y)); }
double triarea(PT a, PT b, PT c) {
  return fabs(trap(a, b) + trap(b, c) + trap(c, a));
}
void closestpt(PT p1, PT p2, PT p3, PT& r) {
  if (fabs(triarea(p1, p2, p3)) < EPS) {
    r = p3;
    return;
  }
  PT v = p2 - p1;
  v.normalize();
  double pr;
  pr = (p3.y - p1.y) * v.y + (p3.x - p1.x) * v.x;
