Shape clean_shape(Shape s) {
  vector<Point> V_clean{s.V[0]};
  int N = s.size();
  for (int i = 1; i < N; i++)
    if (sqrt(dot(s.V[i] - s.V[i - 1], s.V[i] - s.V[i - 1])) > eps)
      V_clean.push_back(s.V[i]);
  return Shape(V_clean);
}
void print_shape(Shape s) {
  s = clean_shape(s);
