void soups_on(void) {
  double res = kInf;
  int r1 = 1, r2 = 1;
  for (int i = 0; i < M; ++i) {
    int low = 0, up = N - 1, mid1, mid2;
    double d1, d2, dt;
    while (low < up) {
      mid1 = (low + up) / 2, mid2 = (up + mid1) / 2;
      d1 = dist(A, Y1[mid1], B, Y2[i]) + dist(A, Y1[mid1], 0, 0);
      d2 = dist(A, Y1[mid2], B, Y2[i]) + dist(A, Y1[mid2], 0, 0);
      if (flt(d1, d2))
        up = mid2 - 1;
      else if (flt(d2, d1))
        low = mid1 + 1;
      else
        low = up = mid1;
    }
    dt = dist(A, Y1[low], B, Y2[i]) + dist(A, Y1[low], 0, 0);
    if (flt(dt + Li[i], res)) res = dt + Li[i], r1 = low, r2 = i;
  }
