struct BIT {
  using T = int;
  vector<T> arr;
  BIT(T s = 1e6 + 1) { arr.assign(s + 1, 0); }
  T sum(T pos) {
    T ans = 0;
    while (pos > 0) {
      ans += arr[pos];
      pos = pos - (pos & (-pos));
    }
    return ans;
  }
  void update(T pos, T val) {
    pos += 1;
    while ((pos > 0) && (pos < arr.size())) {
      arr[pos] += val;
      pos = pos + (pos & (-pos));
    }
  }
