struct Node {
  int l, r, min, cntmin, pushed, vl, vr;
  Node() { l = r = -1; }
  Node(int _vl, int _vr) {
    vl = _vl, vr = _vr;
    l = r = -1;
    min = pushed = 0;
    cntmin = vr - vl + 1;
  }
};
const int MAXN = 7e6, ADD = 1e9;
Node t[MAXN];
int sz = 1;
int get_id(int v, int vl, int vr) {
  if (v == -1) {
    t[sz] = Node(vl, vr);
    return sz++;
  }
  return v;
}
void upd(int v) {
  t[v].min = min(t[t[v].l].min, t[t[v].r].min);
  t[v].cntmin = 0;
  if (t[t[v].l].min == t[v].min) t[v].cntmin += t[t[v].l].cntmin;
  if (t[t[v].r].min == t[v].min) t[v].cntmin += t[t[v].r].cntmin;
}
void push(int v) {
  int val = t[v].pushed;
  int vm = ((long long)t[v].vl + t[v].vr) >> 1;
  t[v].l = get_id(t[v].l, t[v].vl, vm),
  t[v].r = get_id(t[v].r, vm + 1, t[v].vr);
  t[t[v].l].pushed += val, t[t[v].l].min += val;
  t[t[v].r].pushed += val, t[t[v].r].min += val;
  t[v].pushed = 0;
}
void add(int v, int l, int r, int val) {
  if (t[v].vl > r || t[v].vr < l) return;
  if (l <= t[v].vl && t[v].vr <= r) {
    t[v].min += val, t[v].pushed += val;
    return;
  }
  push(v);
  add(t[v].l, l, r, val);
  add(t[v].r, l, r, val);
  upd(v);
}
int zeros(int v, int l, int r) {
  if (t[v].vl > r || t[v].vr < l) return 0;
  if (l <= t[v].vl && t[v].vr <= r) return t[v].cntmin * (t[v].min == 0);
  push(v);
  return zeros(t[v].l, l, r) + zeros(t[v].r, l, r);
}
