template <typename T>
vector<vector<T>> normalize2(const vector<vector<T>> &input) {
  if (input.size() < 2) {
    return input;
  } else {
    vector<vector<T>> e = input;
    if (dot(e[0], e[0]) > dot(e[1], e[1])) {
      swap(e[0], e[1]);
    }
    if (dot(e[0], e[0]) == 0) {
      return vector<vector<T>>{e[1]};
    } else {
      T norm = dot(e[1], e[1]);
      T n_ = (-dot(e[1], e[0])) / dot(e[0], e[0]);
      T n = n_ + sign(n_);
      vector<T> e1_ = wsum(vector<vector<T>>{e[0], e[1]}, vector<T>{n_, 1});
      vector<T> e1 = wsum(vector<vector<T>>{e[0], e[1]}, vector<T>{n, 1});
      vector<vector<T>> res{};
      if (dot(e1, e1) < dot(e1_, e1_)) {
        res = vector<vector<T>>{e[0], e1};
      } else {
        res = vector<vector<T>>{e[0], e1_};
      }
      if (dot(res[1], res[1]) < norm) {
        return normalize2(res);
      } else {
        return res;
      }
    }
  }
}
template <typename T>
class Primes {
