 public:
  Primes(T n) {
    primes = vector<T>{};
    vector<char> mask(n + 1);
    for (int p = 2; p * p <= n; p++) {
      if (mask[p] == 0) {
        for (int i = p * p; i <= n; i += p) {
          mask[i] = 1;
        }
      }
    }
    for (int p = 2; p <= n; p++) {
      if (mask[p] == 0) {
        primes.push_back(p);
      }
    }
  }
  const int size() { return primes.size(); }
  const vector<T> all() { return primes; }
  T operator[](int i) {
    if (0 <= i && i < primes.size()) {
      return primes[i];
    } else {
      throw invalid_argument("wrong index");
    }
  }
};
