    }
  }
};
vector<vector<LLONG>> factors(LLONG x, Primes<LLONG> &p) {
  int i = 0;
  vector<vector<LLONG>> res{};
  while (i < p.size() && p[i] * p[i] <= x) {
    int cnt = 0;
    while (x % p[i] == 0) {
      x = x / p[i];
      ++cnt;
    }
    if (cnt > 0) {
      res.push_back(vector<LLONG>{p[i], cnt});
    }
    ++i;
  }
  if (x != 1) {
    res.push_back(vector<LLONG>{x, 1});
  }
  return res;
}
LLONG mod(LLONG x, LLONG p) {
  LLONG a = x % p;
  if (a < 0) {
    return a + p;
  } else {
    return a;
  }
}
LLONG qresprime(LLONG, LLONG, Primes<LLONG> &primes);
LLONG qres(LLONG q, LLONG p, Primes<LLONG> &primes) {
  q = mod(q, p);
  if (q == 0) {
    return 0;
  } else {
    vector<vector<LLONG>> fs = factors(q, primes);
    LLONG res = 1;
    for (auto f : fs) {
      LLONG cur = qresprime(f[0], p, primes);
      if (cur == -1 && f[1] % 2 == 1) {
        res *= -1;
      }
    }
    return res;
  }
}
LLONG qresprime(LLONG q, LLONG p, Primes<LLONG> &primes) {
  if (mod(q, p) == 2) {
    if (p % 8 == 1 || p % 8 == 7) {
      return 1;
    } else {
      if (p % 8 == 3 || p % 8 == 5) {
        return -1;
      } else {
        throw -1;
      }
    }
  } else {
    LLONG sfactor = (mod(q, 4) == 3 && mod(p, 4) == 3) ? -1 : 1;
    return sfactor * qres(mod(p, q), q, primes);
  }
}
LLONG powermod(LLONG x, LLONG a, LLONG p) {
  LLONG t = x;
  LLONG res = 1;
  while (a > 0) {
    LLONG d = a % 2;
    a = a / 2;
    if (d == 1) {
      res = mod(res * t, p);
    }
    t = mod(t * t, p);
  }
  return res;
}
LLONG imgunit(LLONG p, LLONG a, Primes<LLONG> &primes) {
  if (!(a > 0)) {
    throw -1;
  } else {
    if (p > 2 && p % 4 == 1) {
      for (LLONG q = 2; q < p; ++q) {
        if (qres(q, p, primes) == -1) {
          LLONG degree = powermod(p, a - 1, LLONG_MAX) * (p - 1) / 4;
          LLONG pa = powermod(p, a, LLONG_MAX);
          return powermod(q, degree, pa);
        }
      }
      throw -1;
    } else {
      throw -1;
    }
  }
}
vector<LLONG> euclidstop(LLONG a, LLONG b, LLONG c) {
  if (a * a <= c && b * b <= c) {
