  } else {
    return euclidstop(b, a % b, c);
  }
}
vector<LLONG> egcd_(LLONG a, LLONG b) {
  if (b == 0) {
    return vector<LLONG>{1, 0, a};
  } else {
    LLONG r = a / b;
    LLONG a_ = a - b * r;
    vector<LLONG> res = egcd_(b, a_);
    LLONG d = (res[0] - res[1] * r) / a;
    return vector<LLONG>{res[1] + b * d, res[0] - res[1] * r - a * d, res[2]};
  }
}
vector<LLONG> egcd(LLONG a, LLONG b) {
  if (abs(a) >= abs(b)) {
    return egcd_(a, b);
