template <typename T>
void swap_columns(vector<vector<T>> &a, int i, int j) {
  for (auto &v : a) {
    swap(v[i], v[j]);
  }
}
template <typename T>
void swap_rows(vector<vector<T>> &a, int i, int j) {
  swap(a[i], a[j]);
}
template <typename T>
void reduce_triangular(vector<vector<T>> &a, vector<vector<T>> &r, int i) {
  if (i >= a.size()) {
    return;
  } else {
    int n = r.size();
    int j = i;
    while (j < n && a[i][j] == 0) ++j;
    if (j == n) {
      a.erase(a.begin() + i);
      reduce_triangular(a, r, i);
    } else {
      int j_ = j + 1;
      while (j_ < n && a[i][j_] == 0) ++j_;
      if (j_ == n) {
        swap_columns(a, i, j);
        swap_columns(r, i, j);
        reduce_triangular(a, r, i + 1);
      } else {
        T ma = abs(a[i][j]);
        T tj = j;
        for (j_ = j; j_ < n; ++j_) {
          if (abs(a[i][j_]) < ma && abs(a[i][j_]) != 0) {
            tj = j_;
            ma = abs(a[i][j_]);
          }
        }
        for (j_ = 0; j_ < n; ++j_) {
          if (j_ != tj) {
            T c = a[i][j_] / a[i][tj];
            for (int k = i; k < a.size(); ++k) {
              a[k][j_] = a[k][j_] - c * a[k][tj];
            }
            for (int k = 0; k < n; ++k) {
              r[k][j_] = r[k][j_] - c * r[k][tj];
            }
          }
        }
        reduce_triangular(a, r, i);
      }
    }
  }
}
template <typename T>
vector<vector<T>> efromx(const vector<T> &x) {
  return vector<vector<T>>{
      {x[1] * x[1] - x[2] * x[2] - x[3] * x[3] + x[0] * x[0],
       2 * x[1] * x[2] - 2 * x[3] * x[0], 2 * (x[1] * x[3] + x[2] * x[0])},
      {2 * (x[1] * x[2] + x[3] * x[0]),
       -x[1] * x[1] + x[2] * x[2] - x[3] * x[3] + x[0] * x[0],
       2 * x[2] * x[3] - 2 * x[1] * x[0]},
      {2 * x[1] * x[3] - 2 * x[2] * x[0], 2 * (x[2] * x[3] + x[1] * x[0]),
       -x[1] * x[1] - x[2] * x[2] + x[3] * x[3] + x[0] * x[0]}};
}
template <typename T>
vector<T> axv(const vector<T> &x, const vector<T> &v) {
