vector<vector<LLONG>> reduce2(const vector<vector<LLONG>> &basis_,
                              const vector<LLONG> &v) {
  vector<vector<LLONG>> e = normalize2(basis_);
  if (e.size() == 1) {
    e.push_back(v);
    return normalize2(e);
  } else {
    LLONG original_norm = dot(e[0], e[0]) + dot(e[1], e[1]);
    BIG e00 = dot(e[0], e[0]);
    BIG e11 = dot(e[1], e[1]);
    BIG e01 = dot(e[0], e[1]);
    BIG det2 = e00 * e11 - e01 * e01;
    if (det2 == 0) {
      throw -1;
    }
    BIG v0 = dot(e[0], v);
    BIG v1 = dot(e[1], v);
    BIG nn0 = (v0 * e11 - v1 * e01) / det2;
    BIG nn1 = (-v0 * e01 + v1 * e00) / det2;
    if (!(nn0 <= LLONG_MAX && nn0 >= LLONG_MIN)) throw -1;
    if (!(nn1 <= LLONG_MAX && nn1 >= LLONG_MIN)) throw -1;
    vector<LLONG> n = {(LLONG)nn0, (LLONG)nn1};
    LLONG norm = LLONG_MAX;
    vector<LLONG> v_red_best(v.size());
    for (int d0 = 0; d0 < 2; d0++) {
      for (int d1 = 0; d1 < 2; d1++) {
        vector<LLONG> n_ = {n[0] + sign(n[0]) * d0, n[1] + sign(n[1]) * d1};
        vector<LLONG> v_red = wsum(e, n_);
        add(v, BIG(-1), v_red);
        LLONG norm_cur = dot(v_red, v_red);
        if (norm_cur < norm) {
          v_red_best = v_red;
          norm = norm_cur;
        }
      }
    }
    if (norm == 0) {
      return e;
    } else {
      if (norm < e11) {
        return reduce2(vector<vector<LLONG>>{e[0], v_red_best}, e[1]);
      } else {
        return vector<vector<LLONG>>{e[0], e[1], v_red_best};
      }
    }
  }
