    long double aux = vertice[i].x * vertice[i + 1].y;
    aux -= vertice[i].y * vertice[i + 1].x;
    long double aux_x = (vertice[i].x + vertice[i + 1].x);
    long double aux_y = (vertice[i].y + vertice[i + 1].y);
    C.x += aux * aux_x;
    C.y += aux * aux_y;
