  vector<pair<long long, long long> > line;
  int p = 0;
  void insert(pair<long long, long long> now) {
    int ok = 0;
    do {
      if (line.size() == 0) {
        line.push_back(now);
        ok = 1;
      } else if (line.size() == 1) {
        if (line.back().first < now.first) {
          line.push_back(now);
          ok = 1;
        } else if (line.back().second >= now.second)
          ok = 1;
        else
          line.pop_back();
      } else {
        pair<long long, long long> L1 = line[line.size() - 2], L2 = line.back();
        if ((long double)1.0 * (now.second - L1.second) /
                (L1.first - now.first) >
            (long double)1.0 * (L2.second - L1.second) /
                (L1.first - L2.first)) {
          line.push_back(now);
          ok = 1;
        } else
          line.pop_back();
      }
    } while (!ok);
  }
  long long calc(int mid, long long x) {
    return line[mid].first * x + line[mid].second;
  }
  long long find(long long x) {
    while (p < line.size() - 1 && calc(p, x) <= calc(p + 1, x)) p++;
    return calc(p, x);
  }
};
