//! ll power
ll powmod(int a, int x){ //a^x
    if (x == 0) return 1;
    if (x % 2 == 0){
        ll temp = powmod(a,x/2);
        return (temp*temp) % lp;
    }else{
        ll temp = powmod(a,x/2);
        return ((temp*temp) % lp * a) % lp;
    }
}
ll lpinv(int a){ //inverse of a under the prime
    return powmod(a,lp-2);
}
//! ll ncr offset
ll ncroffset(int n, int r, int n0, int r0, int prev){
    ll ans = prev;
    if (r == 0 || n == r) return 1;

    //*numerator
    if (n > n0){ 
        for (int i=n0+1; i<=n; ++i){
            ans = (ans*i) % lp;
        }
    }else if (n < n0){
        for (int i=n0; i>n; --i){
            ans = (ans*lpinv(i)) % lp;
        }
    }

    //*denominator1
    if (r > r0){
        for (int i=r0+1; i<=r; ++i){
            ans = (ans*lpinv(i)) % lp;
        }
    }else if (r < r0){
        for (int i=r0; i>r; --i){
            ans = (ans*i) % lp;
        }
    }

    //*denominator2
    r = n-r;
    r0 = n0-r0;
    if (r > r0){
        for (int i=r0+1; i<=r; ++i){
            ans = (ans*lpinv(i)) % lp;
        }
    }else if (r < r0){
        for (int i=r0; i>r; --i){
            ans = (ans*i) % lp;
        }
