  vector<line> all(n);
  for (int i = 0; i < n; i++) {
    int a, b, c;
    scanf(" %d %d %d", &a, &b, &c);
    all[i].a = a, all[i].b = b, all[i].c = c;
    all[i].id = i + 1;
  }
