  int y1, y2;
};
rect* intersect(rect* r1, rect* r2) {
  if (r1 == nullptr || r2 == nullptr) {
    return nullptr;
  }
  if (r1->x1 > r2->x2 || r1->x2 < r2->x1) {
    return nullptr;
  }
  if (r1->y1 > r2->y2 || r1->y2 < r2->y1) {
    return nullptr;
  }
  struct rect* temp = (rect*)malloc(sizeof(struct rect));
  temp->x1 = max(r1->x1, r2->x1);
  temp->y1 = max(r1->y1, r2->y1);
  temp->x2 = min(r1->x2, r2->x2);
  temp->y2 = min(r1->y2, r2->y2);
  return temp;
}
