  rect* suf[n];
  suf[n - 1] = rectangles[n - 1];
  for (int i = 1; i < n; i++) {
    pre[i] = intersect(pre[i - 1], rectangles[i]);
  }
  for (int i = n - 2; i >= 0; i--) {
    suf[i] = intersect(suf[i + 1], rectangles[i]);
