def all_perpendicular(vs):
    return all([perpendicular(vs[i], vs[(i+1)%4]) for i in range(4)])

def rect_sides(vs):
    ls = list(map(lambda v: math.hypot(*v), vs))
    return abs(ls[0] - ls[2]) < eps and abs(ls[1] - ls[3]) < eps

def square_sides(vs):
    ls = list(map(lambda v: math.hypot(*v), vs))
    l = ls[0]
    for lx in ls:
        if abs(lx - l) > eps:
