    if (ix > 0) fx = -1;
    if (iy > 0) fy = -1;
    if (L(fx * xx + ix, fy * yy + iy) < L(fx * yy + ix, fy * xx + iy))
      *it = make_pair(fx * xx, fy * yy);
    else
      *it = make_pair(fx * yy, fy * xx);
    ix = it->first + ix;
    iy = it->second + iy;
  }
  sort(e.begin(), e.end(), cmp2);
  puts("YES");
  for (vector<pair<int, int> >::iterator it = e.begin(); it != e.end(); it++) {
    printf("%d %d\n", ix, iy);
    ix += it->first;
    iy += it->second;
  }
