struct line {
  long long a, b, c;
  line(point p1, point p2) {
    this->a = p1.y - p2.y;
    this->b = p2.x - p1.x;
    this->c = -1 * (a * p1.x + b * p1.y);
  }
  line(long long a, long long b, long long c) {
    this->a = a;
    this->b = b;
    this->c = c;
  }
  line() {
    this->a = 0;
    this->b = 0;
    this->c = 0;
  }
  long long sz(point p) { return this->a * p.x + this->b * p.y + this->c; }
};
istream& operator>>(istream& in, line& a) {
  in >> a.a >> a.b >> a.c;
