double angle2(pair<double, double> a, pair<double, double> b) {
  double dx = b.first - a.first, dy = b.second - a.second;
  if (b.first == a.first) {
    if (dy > 0) return acos(-1) / 2;
    return 3 * acos(-1) / 2;
  }
  if (dx >= 0 && dy >= 0) return atan(dy / dx);
  if (dx < 0 && dy >= 0) return acos(-1) - atan(fabs(dy / dx));
  if (dx < 0 && dy < 0) return acos(-1) + atan(dy / dx);
  return 2 * acos(-1) - atan(fabs(dy / dx));
}
double angle(pair<double, double> a, pair<double, double> b,
             pair<double, double> c) {
  double t1 = angle2(b, a), t2 = angle2(b, c);
  return min(fabs(t1 - t2), 2 * acos(-1) - fabs(t1 - t2));
}
double area(pair<double, double> a, pair<double, double> b,
