}
void change(long long int u, long long int v) {
  swap(idx[heap[u]], idx[heap[v]]);
  swap(heap[u], heap[v]);
}
void up(long long int ind) {
  while (ind > 1 && rad[heap[ind]] > rad[heap[ind / 2]]) {
    change(ind, ind / 2);
    ind /= 2;
  }
}
void down(long long int ind) {
  long long int mxp = ind;
  if (2 * ind <= hsz && rad[heap[2 * ind]] > rad[heap[mxp]]) mxp = 2 * ind;
  if (2 * ind + 1 <= hsz && rad[heap[2 * ind + 1]] > rad[heap[mxp]])
    mxp = 2 * ind + 1;
