                   std::pair<long double, long double> b) {
      assert(a.first < b.first);
      long double w = b.first - a.first;
      pb += w;
      if (a.second > b.second) std::swap(a, b);
      events.push_back(std::make_pair(a.second, Ev(0, -w, 0)));
      events.push_back(
          std::make_pair(a.second, Ev(0, 0, w * (b.second + a.second) / 2)));
      if (std::abs(a.second - b.second) < 1e-8) return;
      long double heh = w / (b.second - a.second);
      events.push_back(std::make_pair(
          a.second, Ev(-heh / 2, (long double)b.second * heh,
                       -(long double)b.second * b.second * heh / 2)));
      events.push_back(std::make_pair(
          b.second, Ev(heh / 2, -(long double)b.second * heh,
                       (long double)b.second * b.second * heh / 2)));
