    while (((int)(events).size()) && events.back().first <= x) {
      auto ev = events.back().second;
      events.pop_back();
      pa += ev.a;
      pb += ev.b;
      pc += ev.c;
    }
    return pa * x * x + pb * x + pc;
  }
};
