void add_segment(const complex<double> &p, const complex<double> &q, int k) {
  if (abs(q.real() - p.real()) < 1e-10) return;
  if (p.real() > q.real()) return add_segment(q, p, -k);
  double A = (q.imag() - p.imag()) / (q.real() - p.real());
  double B = p.imag() - p.real() * A;
  ve.emplace_back(p.real(), 0, k * A, k * B);
  ve.emplace_back(q.real(), 0, -k * A, -k * B);
}
complex<double> proj(complex<double> a, complex<double> b, complex<double> p) {
  return {
      (b.real() - a.real()) * (p.imag() - a.imag()) / (b.imag() - a.imag()) +
          a.real(),
      p.imag()};
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> q;
  int j = 0, X, Y, L = 0, R = 0, idx;
  double area = 0, a = 0, b = 0, pos, A, B;
  for (int i = 0; i < n; i++) {
    cin >> X >> Y;
    p[i] = complex<double>(X, Y);
    if (p[i].imag() < p[j].imag()) j = i;
  }
  for (int i = 1; i <= q; i++) {
    cin >> f[i];
    ve.emplace_back(f[i], i, -1, -1);
  }
  for (int i = 0; i < n; i++) {
    int j = (i + 1) % n;
    area += (conj(p[i]) * p[j]).imag();
    if (p[i].imag() > p[j].imag())
      add_segment(p[i], p[j], 1);
    else
      add_segment(p[j], p[i], 1);
  }
  area = abs(0.5 * area);
  rotate(p, p + j, p + n);
  complex<double> mid = p[0], mid2;
  for (int i = 0; i < n - 1; i++) {
    int L2 = L + 1;
    int R2 = (R + n - 1) % n;
    if (p[L2].imag() < p[R2].imag()) {
      mid2 = (p[L2] + proj(p[R], p[R2], p[L2])) * 0.5;
      L = L2;
    } else {
      mid2 = (p[R2] + proj(p[L], p[L2], p[R2])) * 0.5;
      R = R2;
    }
    add_segment(mid, mid2, 2);
    mid = mid2;
  }
  sort(ve.begin(), ve.end());
  for (auto &e : ve) {
    tie(pos, idx, A, B) = e;
    if (idx > 0) {
      ans[idx] = area + (0.5 * a * pos * pos + b * pos);
    } else {
      area -= (0.5 * A * pos * pos + B * pos);
      a += A, b += B;
    }
  }
  cout << fixed << setprecision(6);
  for (int i = 1; i <= q; i++) {
    cout << ans[i] << '\n';
  }
}

