void BFS(int s) {
  queue<states> que;
  states st;
  st.deg = 0;
  st.fu = st.u = s;
  que.push(st);
  while (!que.empty()) {
    states st = que.front();
    que.pop();
    TREE[st.u].deg = st.deg;
    TREE[st.u].fa[0] = st.fu;
    for (int i = 1; i < DEG; i++) TREE[st.u].fa[i] = s;
    for (int tmp = st.fu, num = 1; TREE[tmp].deg; tmp = TREE[st.u].fa[num++])
      TREE[st.u].fa[num] = TREE[tmp].fa[num - 1];
    for (int i = TREE[st.u].head; i != -1; i = edge[i].next) {
      int v = edge[i].to;
      states nst;
      nst.u = v;
      nst.fu = st.u;
      nst.deg = st.deg + 1;
      que.push(nst);
    }
  }
}
int LCA(int x, int y) {
  if (TREE[x].deg > TREE[y].deg) swap(x, y);
  int hx = TREE[x].deg, hy = TREE[y].deg;
  int tx = x, ty = y;
  for (int det = hy - hx, i = 0; det; det >>= 1, i++)
    if (det & 1) ty = TREE[ty].fa[i];
  if (tx == ty) return tx;
  for (int i = DEG - 1; i >= 0; i--) {
    if (TREE[tx].fa[i] == TREE[ty].fa[i]) continue;
    tx = TREE[tx].fa[i];
    ty = TREE[ty].fa[i];
  }
  return TREE[tx].fa[0];
}
