    id.clear();
  }
  bool useless(const pair<int, int> left, const pair<int, int> middle,
               const pair<int, int> right) {
    return 1LL * (middle.second - left.second) * (middle.first - right.first) >=
           1LL * (right.second - middle.second) * (left.first - middle.first);
  }
