    if (xl <= l && r <= xr) return h;
    if (lazy) {
      lc->update(lc->l, lc->r, op.h);
      rc->update(rc->l, rc->r, op.h);
      lazy = false;
    }
    int ret = INT_MAX;
    if (xl <= lc->r) {
      int temp;
      if (lc->l == lc->r)
        temp = lc->h;
      else
        temp = lc->query(xl, xr);
      if (ret > temp) ret = temp;
