    if (min(y, yy) > max(y1, yy1) || min(y1, yy1) > max(y, yy)) {
      if (y1 < yy1) swap(y1, yy1);
      if (y < yy) swap(y, yy);
      int dx = abs(F.a.x - S.b.x);
      int dy = min(abs(yy1 - y), abs(y1 - yy));
      return dx * dx + dy * dy;
    } else
      return (F.a.x - S.a.x) * (F.a.x - S.a.x);
  } else if (F.a.y == F.b.y && S.a.y == S.b.y) {
    int x = F.a.x;
    int xx = F.b.x;
    int x1 = S.a.x;
    int xx1 = S.b.x;
    if (min(x, xx) > max(x1, xx1) || min(x1, xx1) > max(x, xx)) {
      if (x1 < xx1) swap(x1, xx1);
      if (x < xx) swap(x, xx);
      int dy = abs(F.a.y - S.b.y);
      int dx = min(abs(xx1 - x), abs(x1 - xx));
      return dx * dx + dy * dy;
    } else
      return (F.a.y - S.a.y) * (F.a.y - S.a.y);
  } else {
    if (F.a.y == F.b.y) swap(F, S);
    int y = F.b.y;
    int y1 = F.a.y;
    int x = S.a.x;
    int x1 = S.b.x;
    if (y1 < y) swap(y, y1);
    if (x1 < x) swap(x, x1);
    if (S.a.y <= y1 && S.a.y >= y)
      return min((x - F.b.x) * (x - F.b.x), (x1 - F.b.x) * (x1 - F.b.x));
    if (F.a.x >= x && F.a.x <= x1)
      return min((y1 - S.a.y) * (y1 - S.a.y), (y - S.a.y) * (y - S.a.y));
    if (abs(x - F.a.x) > abs(x1 - F.a.x)) swap(x, x1);
    if (abs(y - S.a.y) < abs(y1 - S.a.y)) swap(y, y1);
    int dx = F.a.x - x;
    int dy = y1 - S.a.y;
    return dx * dx + dy * dy;
  }
