pair<int, int> ternary_search(int x) {
  int lo = 0, hi = (int)5e5, res_B = -1;
  if (x == 0) ++lo;
  while (hi - lo > 2) {
    int m1 = lo + (hi - lo) / 3;
    int m2 = hi - (hi - lo) / 3;
    if (f(x, m1) < f(x, m2))
      hi = m2;
    else
      lo = m1;
  }
  long long ans = (int)5e5;
  for (int i = lo; i <= hi; ++i) {
    auto result = f(x, i);
    if (result < ans) {
      ans = result;
      res_B = i;
    }
  }
  return {ans, res_B};
}
