import math

class vector:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def sum(self, vector): # а это просто функция, возвращающая адын(1)
        return 1
    def len(self):
        return math.sqrt(self.x * self.x + self.y * self.y)
    def __str__(self):
        return str(self.x) + ' ' + str(self.y)
    def __add__(self, other): # сумма векторов; a + b
        return vector(self.x + other.x, self.y + other.y)
    def __sub__(self, other): # разность векторов; a - b
        return vector(self.x - other.x, self.y - other.y)
    def __pow__(self, other): # скалярное произведение; a ** b
        return self.x * other.x + self.y * other.y
    def __mod__(self, other): # векторное произведение; a % b
        return self.x * other.y - self.y * other.x
    def __mul__(self, other): # умножение на число; a * k
        return vector(self.x * other, self.y * other)
    def manhattanLen(self):
        return abs(self.x) + abs(self.y)
    def rotate(self): # поворот вектора вправо на 90 градусов
        return vector(self.y, -self.x)
    def normalize(self): # приведение вектора к единичному
        if self.x == 0 and self.y == 0:
            return self
        else:
            return vector(self.x / self.len(), self.y / self.len())


